SELECT t."类别" AS "类别",(t."主档状态").name AS "主档状态",COUNT(t.rec_id) AS total FROM "Materials" AS t INNER JOIN "Members" AS access_member ON (access_member."用户").id = CURRENT_USER_ID() LEFT JOIN "Roles" AS access_role ON access_member."角色编码" = access_role."角色编码" WHERE (access_member."状态").name = '启用' AND (((access_member."角色编码" IS NULL AND (access_member."角色").name IN ('管理员','采购','中央仓','技术','只读')) OR (access_role."启用" = TRUE AND access_role."权限代码" LIKE '%|dashboard.view|%')) OR ((access_member."角色编码" IS NULL AND (access_member."角色").name IN ('管理员','采购','中央仓','技术','只读')) OR (access_role."启用" = TRUE AND access_role."权限代码" LIKE '%|reports.view|%'))) GROUP BY t."类别",(t."主档状态").name LIMIT 10000